        {studentEditor&&<form onSubmit={saveStudent} className={styles.studentEditor}><div className={styles.assessmentTitle}><h3>{studentEditor.mode==='add'?'Add a student':'Edit student details'}</h3><button type="button" onClick={()=>{if(leave()){setStudentEditor(null);setDirty(false);}}}>Close</button></div><div className={styles.formGrid}><label>Student name<input name="name" required maxLength={200} defaultValue={studentEditor.student?.name||''} onChange={()=>setDirty(true)}/></label><label>Participant ID<input name="code" required maxLength={80} defaultValue={studentEditor.student?.participant_code||participantCode} onChange={()=>setDirty(true)}/><small>Generated automatically; you can change it if needed.</small></label><label>School / program<select name="site" required defaultValue={studentEditor.student?.site_id||site} onChange={()=>setDirty(true)}><option value="">Choose school / program</option>{sites.map(s=><option value={s.id} key={s.id}>{siteLabel(s.id)}</option>)}</select></label></div><button disabled={busy} className={styles.primary}>{studentEditor.mode==='add'?'Add student':'Save changes'}</button></form>}
